function findMatchingPresetKey(name, model) {
  name = (name || '').toLowerCase().trim();
  model = (model || '').toLowerCase().trim();
  var combined = (name + ' ' + model).trim();
  if (!combined) return null;

  var words = combined.split(/[\s,;+\-_/()]+/);
  var combinedCompact = combined.replace(/[\s\-_]+/g, '');

  for (var pKey in MODEL_PRESETS) {
    var p = MODEL_PRESETS[pKey];
    if (p.model && p.model.length >= 3) {
      var pModL = p.model.toLowerCase().trim();
      var pModCompact = pModL.replace(/[\s\-_]+/g, '');
      if (words.includes(pModL) || combined === pModL || (pModCompact.length >= 4 && combinedCompact.includes(pModCompact))) {
        return pKey;
      }
    }
    if (p.name && combined === p.name.toLowerCase().trim()) {
      return pKey;
    }
  }
  return null;
}

function cleanAndParseJsonArray(rawText) {
  if (!rawText) return null;
  var clean = rawText.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();
  var startIdx = clean.indexOf('[');
  var endIdx = clean.lastIndexOf(']');
  if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
    try {
      var arr = JSON.parse(clean.slice(startIdx, endIdx + 1));
      if (Array.isArray(arr) && arr.length > 0) return arr;
    } catch (e) { }
  }
  return null;
}

