function handleDevPriceInput(el, id) {
  var num = formatMoneyInput(el);
  upD(id, 'price', num);
}

function upD(id, f, v) {
  var d = devs.find(function (x) { return x.id === id; }); if (!d) return;
  d[f] = v;
  if (f === 'qty' || f === 'price') {
    var el = document.getElementById('tt' + id);
    if (el) el.value = fmtV((d.qty || 0) * (d.price || 0));
  }
  syncDeviceSpecs(d);
  renderCurrentSheetView();
}
function upSp(did, i, f, v) {
  var d = devs.find(function (x) { return x.id === did; });
  if (d && d.specs[i]) {
    d.specs[i][f] = v;
    syncDeviceSpecs(d);
    renderCurrentSheetView();
  }
}
function addSp(did) {
  var d = devs.find(function (x) { return x.id === did; }); if (!d) return;
  d.specs.push({ key: '', value: '' });
  var sel = document.getElementById('quickDevSelect');
  renderEditForm(sel ? +sel.value : 0);
  renderCurrentSheetView();
}
function rmSp(did, i) {
  var d = devs.find(function (x) { return x.id === did; }); if (!d) return;
  d.specs.splice(i, 1);
  var sel = document.getElementById('quickDevSelect');
  renderEditForm(sel ? +sel.value : 0);
  renderCurrentSheetView();
}
function rmD(id) {
  if (!confirm('Bạn có chắc muốn xóa thiết bị này?')) return;
  devs = devs.filter(function (d) { return d.id !== id; });
  buildStep2();
}
function addDev() {
  var id = ++devCnt;
  devs.push({ id: id, stt: devs.length + 1, name: 'Thiết bị mới', model: '', brand: '', origin: '', unit: 'Máy', qty: 1, price: 0, warranty: '', specs: [{ key: 'Xuất xứ', value: '' }, { key: 'Bảo hành', value: '12 tháng' }] });
  buildStep2();
}

function handleDirectExportFromStep1() {
  if ((!devs || devs.length === 0) && typeof selectedCatalogItems !== 'undefined' && Object.keys(selectedCatalogItems).length > 0) {
    createProjectFromCatalog();
  }
  if (!devs || devs.length === 0) {
    toast('⚠️ Vui lòng chọn thiết bị từ danh mục hoặc tải file lên trước khi xuất Excel!', 'err');
    return;
  }
  doExport();
}

/* ═══════════════════════════════════════════
   STEP 3 / EXPORT EXCEL (100% MATCH TO IMAGES 1 & 2)
═══════════════════════════════════════════ */
function buildFinal() {
  document.getElementById('finalSheetArea').innerHTML = buildSummaryTableHtml();
}

function doExport() {
  if (!devs.length) { toast('❌ Không có dữ liệu để xuất!', 'err'); return; }
  var b = document.getElementById('btnExp');
  b.disabled = true; b.innerHTML = '<span class="spin-w"></span> Đang tạo file Excel...';
  try {
    var wb = XLSX.utils.book_new();
    xlsTH(wb);
    devs.forEach(function (d, i) { xlsSP(wb, d, i + 1); });
    var pn = (document.getElementById('pjN').value || 'DuToan').replace(/[\\/:*?"<>|]/g, '_').substring(0, 40);
    var fileName = 'DuToan_' + pn + '_' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '.xlsx';
    XLSX.writeFile(wb, fileName);
    // === GHI LỊCH SỬ ===
    var totalVal = devs.reduce(function(s,d){ return s + (d.qty||0)*(d.price||0); }, 0);
    lsAddEntry('dutoan',
      pn || 'Dự toán mới',
      fileName,
      {
        project: pn,
        devices: devs.length,
        total: totalVal > 0 ? totalVal.toLocaleString('vi-VN') + ' ₫' : ''
      }
    );
    toast('✅ Xuất file Excel thành công!', 'ok');
  } catch (e) { console.error(e); toast('❌ Lỗi: ' + e.message, 'err'); }
  b.disabled = false; b.innerHTML = '⬇️ Tải file Excel dự toán (.xlsx)';
}

function mkB(c) { var b = { style: 'thin', color: { rgb: c || '000000' } }; return { top: b, bottom: b, left: b, right: b }; }

function setCell(ws, r, c, val, style) {
  var ref = XLSX.utils.encode_cell({ r: r, c: c });
  var t = typeof val === 'number' ? 'n' : 's';
  ws[ref] = { t: t, v: val, s: style };
}

/* ── SHEET "TỔNG HỢP" (100% IDENTICAL TO IMAGE 1 & CHUẨN MẪU DỰ TOÁN) ── */
function xlsTH(wb) {
  var ws = {}; var mg = [];

  // STYLES FROM ORIGINAL TEMPLATE
  var STITLE = { font: { bold: true, name: 'Times New Roman', sz: 14, color: { rgb: '000000' } }, alignment: { horizontal: 'center', vertical: 'center' } };
  var SORG = { font: { bold: true, name: 'Times New Roman', sz: 11, color: { rgb: '000000' } }, alignment: { horizontal: 'left', vertical: 'center' } };
  var SDATE = { font: { italic: true, name: 'Times New Roman', sz: 11, color: { rgb: '000000' } }, alignment: { horizontal: 'right', vertical: 'center' } };
  var SPJ_LEFT = { font: { bold: true, name: 'Times New Roman', sz: 11, color: { rgb: '000000' } }, alignment: { horizontal: 'left', vertical: 'center', wrapText: true } };
  var SGP_LEFT = { font: { italic: true, bold: true, name: 'Times New Roman', sz: 10.5, color: { rgb: '333333' } }, alignment: { horizontal: 'left', vertical: 'center', wrapText: true } };

  var SH = { font: { bold: true, name: 'Times New Roman', sz: 11, color: { rgb: '000000' } }, fill: { patternType: 'solid', fgColor: { rgb: 'D9E1F2' } }, alignment: { horizontal: 'center', vertical: 'center', wrapText: true }, border: mkB('000000') };
  var SA = { font: { bold: true, name: 'Times New Roman', sz: 11, color: { rgb: '000000' } }, alignment: { vertical: 'center' }, border: mkB('000000') };
  var SI = { font: { bold: true, name: 'Times New Roman', sz: 11, color: { rgb: '000000' } }, alignment: { vertical: 'center' }, border: mkB('000000') };
  var SAC = { font: { bold: true, name: 'Times New Roman', sz: 11, color: { rgb: '000000' } }, alignment: { horizontal: 'center', vertical: 'center', wrapText: true }, border: mkB('000000') };
  var SD = { font: { name: 'Times New Roman', sz: 11 }, border: mkB('000000'), alignment: { vertical: 'center', wrapText: true } };
  var SC = { font: { name: 'Times New Roman', sz: 11 }, border: mkB('000000'), alignment: { horizontal: 'center', vertical: 'center', wrapText: true } };
  var SN = { font: { name: 'Times New Roman', sz: 11 }, border: mkB('000000'), alignment: { horizontal: 'right', vertical: 'center' }, numFmt: '#,##0' };
  var SNT = { font: { bold: true, name: 'Times New Roman', sz: 11 }, border: mkB('000000'), alignment: { horizontal: 'right', vertical: 'center' }, numFmt: '#,##0' };

  ws['!cols'] = [{ wch: 6 }, { wch: 48 }, { wch: 22 }, { wch: 18 }, { wch: 18 }, { wch: 10 }, { wch: 8 }, { wch: 20 }, { wch: 20 }];
  ws['!rows'] = []; var r = 0;

  var pjVal = (document.getElementById('pjN') ? document.getElementById('pjN').value : '').trim() || 'Đầu tư nâng cấp hạ tầng số, thiết bị phát triển khoa học và công nghệ';
  var gpVal = (document.getElementById('gpN') ? document.getElementById('gpN').value : '').trim() || 'Hệ thống trang thiết bị CNTT, thiết bị ngoại vi…';
  var orgVal = (document.getElementById('orgN') ? document.getElementById('orgN').value : '').trim() || 'CÔNG TY TNHH THƯƠNG MẠI ĐẦU TƯ VÀ SẢN XUẤT THUẬN PHÁT';
  var dtRaw = document.getElementById('dtN') ? document.getElementById('dtN').value : '';
  if (!dtRaw) {
    var now = new Date();
    dtRaw = now.toISOString().slice(0, 10);
  }
  var dtParts = (dtRaw || '').split('-');
  var dtFormatted = '';
  var dtShort = '';
  if (dtParts.length === 3 && dtParts[0].length === 4) {
    dtFormatted = 'Ngày ' + dtParts[2] + ' tháng ' + dtParts[1] + ' năm ' + dtParts[0];
    dtShort = dtParts[2] + '/' + dtParts[1] + '/' + dtParts[0];
  } else {
    dtFormatted = dtRaw;
    dtShort = dtRaw;
  }

  // 1. Top Header Row: ĐƠN VỊ LẬP (Góc trên bên trái Cols 0-5) | NGÀY LẬP (Góc trên bên phải Cols 6-8)
  setCell(ws, r, 0, 'ĐƠN VỊ LẬP: ' + orgVal.toUpperCase(), SORG);
  for (var c = 1; c <= 5; c++) setCell(ws, r, c, '', SORG);
  mg.push({ s: { r: r, c: 0 }, e: { r: r, c: 5 } });

  setCell(ws, r, 6, 'NGÀY LẬP: ' + (dtFormatted ? dtFormatted : dtShort), SDATE);
  for (var c = 7; c <= 8; c++) setCell(ws, r, c, '', SDATE);
  mg.push({ s: { r: r, c: 6 }, e: { r: r, c: 8 } });
  ws['!rows'][r] = { hpt: 22 };
  r++;

  // 2. Project / Package Row (Góc trên bên trái Cols 0-6)
  setCell(ws, r, 0, 'DỰ ÁN / GÓI THẦU: ' + pjVal, SPJ_LEFT);
  for (var c = 1; c <= 6; c++) setCell(ws, r, c, '', SPJ_LEFT);
  mg.push({ s: { r: r, c: 0 }, e: { r: r, c: 6 } });
  var pjLines = Math.ceil(pjVal.length / 65);
  ws['!rows'][r] = { hpt: Math.max(22, pjLines * 18 + 4) };
  r++;

  // 3. Group Row (Góc trên bên trái Cols 0-6)
  setCell(ws, r, 0, 'NHÓM DANH MỤC: ' + gpVal, SGP_LEFT);
  for (var c = 1; c <= 6; c++) setCell(ws, r, c, '', SGP_LEFT);
  mg.push({ s: { r: r, c: 0 }, e: { r: r, c: 6 } });
  ws['!rows'][r] = { hpt: 20 };
  r++;

  // 4. Spacing row
  ws['!rows'][r] = { hpt: 8 };
  r++;

  // 5. Title Row: BẢNG TỔNG HỢP DỰ TOÁN THIẾT BỊ (Căn giữa Cols 0-8)
  setCell(ws, r, 0, 'BẢNG TỔNG HỢP DỰ TOÁN THIẾT BỊ', STITLE);
  for (var c = 1; c <= 8; c++) setCell(ws, r, c, '', STITLE);
  mg.push({ s: { r: r, c: 0 }, e: { r: r, c: 8 } });
  ws['!rows'][r] = { hpt: 28 };
  r++;

  // 6. Spacing row
  ws['!rows'][r] = { hpt: 8 };
  r++;

  // 7. Table Header row: Background #D9E1F2, black text, bold, centered, bordered
  ['STT', 'Danh mục', 'Model', 'Hãng', 'Xuất xứ', 'ĐVT', 'SL', 'Đơn giá (Đã gồm VAT)', 'Thành tiền'].forEach(function (v, c) {
    setCell(ws, r, c, v, SH);
  });
  ws['!rows'][r] = { hpt: 32 }; r++;

  var dataStartRow = r;
  devs.forEach(function (d, i) {
    var t = (d.qty || 0) * (d.price || 0);
    setCell(ws, r, 0, i + 1, SC);
    setCell(ws, r, 1, d.name || '', SD);
    setCell(ws, r, 2, d.model || '', SC);
    setCell(ws, r, 3, d.brand || '', SC);
    setCell(ws, r, 4, d.origin || '', SC);
    setCell(ws, r, 5, d.unit || 'Máy', SC);
    setCell(ws, r, 6, d.qty || 1, SC);

    var gR = XLSX.utils.encode_cell({ r: r, c: 6 });
    var hR = XLSX.utils.encode_cell({ r: r, c: 7 });
    var iR = XLSX.utils.encode_cell({ r: r, c: 8 });
    if (d.price && Number(d.price) > 0) {
      ws[hR] = { t: 'n', v: Number(d.price), s: SN };
      ws[iR] = { t: 'n', f: gR + '*' + hR, v: t, s: SN };
    } else {
      ws[hR] = { t: 's', v: '', s: SN };
      ws[iR] = { t: 's', f: 'IF(ISNUMBER(' + hR + '),' + gR + '*' + hR + ',"")', v: '', s: SN };
    }

    // HYPERLINK directly to that device's spec sheet ('1', '2', '3'...)
    var targetSheet = String(i + 1);
    var sttRef = XLSX.utils.encode_cell({ r: r, c: 0 });
    var nameRef = XLSX.utils.encode_cell({ r: r, c: 1 });
    if (ws[sttRef]) ws[sttRef].l = { Target: "#'" + targetSheet + "'!A1" };
    if (ws[nameRef]) ws[nameRef].l = { Target: "#'" + targetSheet + "'!A1" };

    var nameLines = Math.ceil(String(d.name || '').length / 42);
    ws['!rows'][r] = { hpt: Math.max(24, nameLines * 18 + 6) };
    r++;
  });

  // 8. Total Row (TỔNG CỘNG)
  var dataEndRow = r - 1;
  setCell(ws, r, 0, '', SAC);
  setCell(ws, r, 1, 'TỔNG CỘNG', SAC);
  for (var c = 2; c <= 7; c++) setCell(ws, r, c, '', SAC);
  var sumFormula = 'SUM(I' + (dataStartRow + 1) + ':I' + (dataEndRow + 1) + ')';
  var totalVal = devs.reduce(function(s, d) { return s + (d.qty || 0) * (d.price || 0); }, 0);
  var sumRef = XLSX.utils.encode_cell({ r: r, c: 8 });
  ws[sumRef] = { t: 'n', f: sumFormula, v: totalVal, s: SNT };
  ws['!rows'][r] = { hpt: 26 };
  r++;

  ws['!merges'] = mg;
  ws['!ref'] = XLSX.utils.encode_range({ s: { r: 0, c: 0 }, e: { r: r - 1, c: 8 } });
  XLSX.utils.book_append_sheet(wb, ws, 'Tổng hợp');
}

/* ── SHEET SPEC "1, 2, 3..." (100% IDENTICAL TO IMAGE 2) ── */
function xlsSP(wb, dev, num) {
  var ws = {}; var mg = [];

  var pjVal = (document.getElementById('pjN') ? document.getElementById('pjN').value : '').trim() || 'Đầu tư nâng cấp hạ tầng số, thiết bị phát triển khoa học và công nghệ';
  var orgVal = (document.getElementById('orgN') ? document.getElementById('orgN').value : '').trim() || 'CÔNG TY TNHH THƯƠNG MẠI ĐẦU TƯ VÀ SẢN XUẤT THUẬN PHÁT';
  var dtRaw = document.getElementById('dtN') ? document.getElementById('dtN').value : '';
  var dtParts = (dtRaw || '').split('-');
  var dtShort = (dtParts.length === 3 && dtParts[0].length === 4) ? (dtParts[2] + '/' + dtParts[1] + '/' + dtParts[0]) : dtRaw;

  var SINFO = { font: { italic: true, name: 'Times New Roman', sz: 9.5, color: { rgb: '555555' } }, alignment: { vertical: 'center' } };
  // Header "Thông số kỹ thuật": D9E1F2 fill giống sheet Tổng hợp
  var SH  = { font: { bold: true, name: 'Times New Roman', sz: 11, color: { rgb: '000000' } }, fill: { patternType: 'solid', fgColor: { rgb: 'D9E1F2' } }, alignment: { horizontal: 'center', vertical: 'center' }, border: mkB('000000') };
  // Tên thiết bị: cùng màu header cho nổi bật
  var SHL = { font: { bold: true, name: 'Times New Roman', sz: 11, color: { rgb: '1F3864' } }, fill: { patternType: 'solid', fgColor: { rgb: 'D9E1F2' } }, alignment: { vertical: 'center', wrapText: true }, border: mkB('000000') };
  // Cột tên thông số (key): chữ đậm, không màu nền
  var SK  = { font: { bold: true, name: 'Times New Roman', sz: 11 }, border: mkB('000000'), alignment: { vertical: 'center', wrapText: true } };
  // Cột giá trị (value): chữ thường, không màu nền
  var SV  = { font: { name: 'Times New Roman', sz: 11 }, border: mkB('000000'), alignment: { vertical: 'center', wrapText: true } };
  var SQ  = { font: { bold: true, name: 'Times New Roman', sz: 11, color: { rgb: '000000' } }, fill: { patternType: 'solid', fgColor: { rgb: 'FFFF00' } }, alignment: { horizontal: 'center', vertical: 'center' }, border: mkB('000000') };

  // Columns: A (Key/Spec name: 38), B (Value 1: 38), C (Value 2: 38), D (Spacer: 4), E (QUAY LẠI: 16)
  ws['!cols'] = [{ wch: 38 }, { wch: 38 }, { wch: 38 }, { wch: 4 }, { wch: 16 }];
  ws['!rows'] = []; var r = 0;

  // 1. Header info on top of detail sheet (no duplicate QUAY LẠI here)
  if (pjVal || orgVal) {
    var infoTxt = (orgVal ? 'ĐƠN VỊ LẬP: ' + orgVal + '   |   ' : '') + (pjVal ? 'DỰ ÁN: ' + pjVal : '') + (dtShort ? '   |   ' + dtShort : '');
    setCell(ws, r, 0, infoTxt, SINFO);
    for (var c = 1; c <= 2; c++) setCell(ws, r, c, '', SINFO);
    mg.push({ s: { r: r, c: 0 }, e: { r: r, c: 2 } });
    ws['!rows'][r] = { hpt: 20 }; r++;
  }

  // 2. Table Header: Blank (col A) | Thông số kỹ thuật (merged B:C) | Single QUAY LẠI button (col E)
  setCell(ws, r, 0, '', SH);
  setCell(ws, r, 1, 'Thông số kỹ thuật', SH);
  setCell(ws, r, 2, '', SH);
  mg.push({ s: { r: r, c: 1 }, e: { r: r, c: 2 } });

  // Single Yellow QUAY LẠI button at Col E (Col 4) with hyperlink back to Sheet "Tổng hợp"
  var qRef = XLSX.utils.encode_cell({ r: r, c: 4 });
  ws[qRef] = { t: 's', v: 'QUAY LẠI', l: { Target: "#'Tổng hợp'!A1" }, s: SQ };
  ws['!rows'][r] = { hpt: 28 }; r++;

  // 3. Device Name (merged A:C)
  setCell(ws, r, 0, dev.name || '', SHL);
  setCell(ws, r, 1, '', SHL);
  setCell(ws, r, 2, '', SHL);
  mg.push({ s: { r: r, c: 0 }, e: { r: r, c: 2 } });

  var dNameLines = Math.ceil(String(dev.name || '').length / 60);
  ws['!rows'][r] = { hpt: Math.max(26, dNameLines * 18 + 6) }; r++;

  // 4. Specs rows: Col A: Key | Col B..C: Value merged
  dev.specs.forEach(function (sp) {
    if (!sp.key && !sp.value) return;
    setCell(ws, r, 0, sp.key || '', SK);
    setCell(ws, r, 1, sp.value || '', SV);
    setCell(ws, r, 2, '', SV);
    mg.push({ s: { r: r, c: 1 }, e: { r: r, c: 2 } });

    // Dynamic height calculation so no text is cut off
    var keyLines = Math.ceil(String(sp.key || '').length / 28);
    var valLines = 0;
    String(sp.value || '').split(/\r?\n/).forEach(function (line) {
      valLines += Math.max(1, Math.ceil((line.length || 1) / 52));
    });
    var totalLines = Math.max(1, keyLines, valLines);
    ws['!rows'][r] = { hpt: Math.max(22, Math.min(260, totalLines * 16 + 8)) };
    r++;
  });

  ws['!merges'] = mg;
  ws['!ref'] = XLSX.utils.encode_range({ s: { r: 0, c: 0 }, e: { r: r - 1, c: 4 } });
  XLSX.utils.book_append_sheet(wb, ws, String(num));
}

/* ═══════════════════════════════════════════
   HELPERS
═══════════════════════════════════════════ */
function escH(s) { return String(s || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function fmtVN(n) { if (!n && n !== 0) return ''; return Number(n).toLocaleString('en-US'); }
function fmtV(n) { if (!n && n !== 0) return '—'; return Number(n).toLocaleString('vi-VN') + ' đ'; }
function toast(msg, type) {
  var el = document.getElementById('toast');
  document.getElementById('tm').textContent = msg;
  document.getElementById('ti').textContent = type === 'ok' ? '✅' : type === 'ai-t' ? '🤖' : '❌';
  el.className = 'on ' + (type === 'ai-t' ? 'ai-t' : type || 'ok');
  setTimeout(function () { el.className = ''; }, 4000);
}

/* ═══════════════════════════════════════════
   STEP 4 / BIÊN BẢN BÀN GIAO (WORD EXPORT)
═══════════════════════════════════════════ */
function renderHandoverForm() {
  if (!document.getElementById('bbDate').value) {
    document.getElementById('bbDate').valueAsDate = new Date();
  }

  // Danh sách toàn bộ sản phẩm đang hoạt động từ CATALOG_ITEMS hoặc MODEL_PRESETS
  var availableProducts = [];
  if (typeof CATALOG_ITEMS !== 'undefined' && Array.isArray(CATALOG_ITEMS) && CATALOG_ITEMS.length > 0) {
    availableProducts = CATALOG_ITEMS.filter(function (it) { return !it.isLocked; });
  }

  var html = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px">' +
    '<div style="font-weight:700;font-size:14px;color:#0f172a">Danh sách thiết bị bàn giao &amp; Số Serial (Mỗi serial trên 1 dòng)</div>' +
    '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">' +
    '<button class="btn btn-p btn-sm" onclick="bbAddDev()">➕ Thêm dòng mới</button>' +
    (typeof devs !== 'undefined' && devs && devs.length > 0 ? '<button class="btn btn-o btn-sm" style="color:var(--p);font-weight:700" onclick="bbSyncFromDutoan()" title="Đồng bộ danh sách thiết bị đang làm trong tab Dự Toán">📥 Lấy từ Dự Toán (' + devs.length + ' máy)</button>' : '') +
    '<button class="btn btn-o btn-sm" style="color:var(--re);border-color:rgba(207,34,46,0.3)" onclick="bbResetAll()" title="Xóa trắng để lập biên bản mới">🗑️ Làm mới biên bản</button>' +
    '</div>' +
    '</div>';

  html += '<table class="excel-table" style="width:100%">' +
    '<thead><tr><th style="width:40px">STT</th><th>Danh Mục Hàng Hóa &amp; Model (Có thể gõ hoặc chọn từ menu ▾)</th><th style="width:70px">SL</th><th style="width:70px">ĐVT</th><th style="width:340px">Số Serial (Mỗi serial 1 dòng / phân bổ 2 cột)</th><th style="width:50px">Xóa</th></tr></thead><tbody>';

  if (bbDevs.length === 0) {
    html += '<tr><td colspan="6" class="ctr" style="padding:32px 20px;color:var(--t2);background:#ffffff">' +
      '<div style="font-size:32px;margin-bottom:8px">📝</div>' +
      '<div style="font-size:14px;font-weight:700;color:#0f172a;margin-bottom:4px">Chưa có thiết bị nào trong biên bản bàn giao</div>' +
      '<div style="font-size:12.5px;color:var(--t2);margin-bottom:14px">Bấm nút "Thêm dòng mới" bên dưới để nhập thiết bị hoặc chọn nhanh từ danh mục mẫu máy có trong hệ thống</div>' +
      '<div style="display:flex;gap:10px;justify-content:center">' +
      '<button class="btn btn-p btn-sm" onclick="bbAddDev()">➕ Thêm dòng mới</button>' +
      (typeof devs !== 'undefined' && devs && devs.length > 0 ? '<button class="btn btn-o btn-sm" style="color:var(--p);font-weight:700" onclick="bbSyncFromDutoan()">📥 Lấy ' + devs.length + ' máy từ Dự Toán</button>' : '') +
      '</div>' +
      '</td></tr>';
  } else {
    bbDevs.forEach(function (d, i) {
      // Xây dựng danh sách option cho mũi tên chọn mẫu máy có trong hệ thống
      var optHtml = '<option value="">▾ Chọn mẫu máy trong kho dự toán...</option>';
      if (availableProducts.length > 0) {
        availableProducts.forEach(function (it) {
          var label = (it.name || '') + (it.model ? ' - ' + it.model : '');
          optHtml += '<option value="' + escH(label) + '|' + escH(it.unit || 'Máy') + '">' + escH(label) + '</option>';
        });
      } else if (typeof MODEL_PRESETS !== 'undefined') {
        for (var pKey in MODEL_PRESETS) {
          var p = MODEL_PRESETS[pKey];
          var label = (p.name || '') + (p.model ? ' - ' + p.model : '');
          optHtml += '<option value="' + escH(label) + '|' + escH(p.unit || 'Máy') + '">' + escH(label) + '</option>';
        }
      }

      html += '<tr>' +
        '<td class="ctr" style="font-weight:700">' + (i + 1) + '</td>' +
        '<td>' +
        '  <div style="display:flex;gap:6px;align-items:center">' +
        '    <input type="text" class="key-inp" style="flex:1;font-weight:600;min-width:180px" value="' + escH(d.name || '') + '" oninput="bbDevs[' + i + '].name=this.value" placeholder="Nhập tên thiết bị hoặc chọn từ menu ▾">' +
        '    <select class="key-inp" style="width:40px;padding:0;text-align:center;cursor:pointer;font-weight:700;font-size:14px;background:#f8fafc;border-color:var(--bdr2);color:var(--p)" title="Chọn mẫu máy có sẵn trong kho dự toán" onchange="bbSelectDeviceForCurrentRow(' + i + ', this.value);this.value=\'\';">' +
        optHtml +
        '    </select>' +
        '  </div>' +
        '</td>' +
        '<td class="ctr"><input type="number" class="key-inp" style="width:100%;text-align:center;font-weight:700" value="' + (d.qty || 1) + '" oninput="bbDevs[' + i + '].qty=this.value"></td>' +
        '<td class="ctr"><input type="text" class="key-inp" style="width:100%;text-align:center" value="' + escH(d.unit || 'Máy') + '" oninput="bbDevs[' + i + '].unit=this.value"></td>' +
        '<td><textarea class="key-inp" style="width:100%;height:75px;resize:vertical;font-family:monospace;font-size:12px;text-align:center" oninput="bbDevs[' + i + '].serials=this.value" placeholder="Dán danh sách serials vào đây (tự động chia 2 cột đều nhau và căn giữa)...">' + escH(d.serials || '') + '</textarea></td>' +
        '<td class="ctr"><button class="btn btn-o btn-sm" style="color:var(--re);border-color:rgba(207,34,46,0.3)" onclick="bbRemoveDev(' + i + ')" title="Xóa thiết bị này">✕</button></td>' +
        '</tr>';
    });
  }
  html += '</tbody></table>';

  document.getElementById('bbTableArea').innerHTML = html;
}

/* ── CHỌN MẪU MÁY TỪ DANH MỤC DỰ TOÁN CHO TỪNG DÒNG THIẾT BỊ ── */
function bbSelectDeviceForCurrentRow(rowIdx, rawVal) {
  if (!rawVal || !bbDevs[rowIdx]) return;
  var parts = rawVal.split('|');
  var devName = parts[0] || '';
  var devUnit = parts[1] || 'Máy';
  bbDevs[rowIdx].name = devName;
  bbDevs[rowIdx].unit = devUnit;
  renderHandoverForm();
  toast('✅ Đã nạp thiết bị: ' + devName, 'ok');
}

