// ══════════════════════════════════════════════════════════════════════════════
// PRODUCT SPECIFICATION INSPECTOR MODAL & DEEP FILTERING
// ══════════════════════════════════════════════════════════════════════════════

var currentSpecModalItemId = null;
var currentSpecModalList = [];

function getDeviceSpecs(item) {
  if (!item) return [];
  if (item.presetKey && typeof MODEL_PRESETS !== 'undefined' && MODEL_PRESETS[item.presetKey] && MODEL_PRESETS[item.presetKey].specs && MODEL_PRESETS[item.presetKey].specs.length) {
    return MODEL_PRESETS[item.presetKey].specs;
  }
  if (typeof MODEL_PRESETS !== 'undefined' && MODEL_PRESETS[item.id] && MODEL_PRESETS[item.id].specs && MODEL_PRESETS[item.id].specs.length) {
    return MODEL_PRESETS[item.id].specs;
  }
  if (item.specs && item.specs.length) {
    return item.specs;
  }
  if (typeof scrapeSmart26Specs === 'function') {
    return scrapeSmart26Specs(item.name || '', item.model || '', item.brand || '');
  }
  return [];
}

var specDisplayMode = 'grid'; // 'grid' (2-column compact) or 'table'

function setSpecDisplayMode(mode) {
  specDisplayMode = mode;
  var btnGrid = document.getElementById('btnSpecViewGrid');
  var btnTable = document.getElementById('btnSpecViewTable');
  var gridWrap = document.getElementById('specCompactGrid');
  var tableWrap = document.getElementById('specTableWrap');

  if (btnGrid) btnGrid.className = 'spec-view-btn' + (mode === 'grid' ? ' active' : '');
  if (btnTable) btnTable.className = 'spec-view-btn' + (mode === 'table' ? ' active' : '');

  if (gridWrap && tableWrap) {
    if (mode === 'grid') {
      gridWrap.style.display = 'grid';
      tableWrap.style.display = 'none';
    } else {
      gridWrap.style.display = 'none';
      tableWrap.style.display = 'block';
    }
  }
}

function extractKeyHighlights(specs) {
  var list = [];
  specs.forEach(function (sp) {
    var k = (sp.key || '').toLowerCase();
    var v = (sp.value || '').trim();
    if (list.length >= 6) return;

    if (/processor|cpu/i.test(k) && !list.some(function (x) { return x.key === 'CPU'; })) {
      list.push({ icon: '⚡', key: 'CPU', val: v.split('\n')[0].split(',')[0].substring(0, 40) });
    } else if (/(^ram|\bram\b|dung lượng ram|bộ nhớ ram)/i.test(k) && !list.some(function (x) { return x.key === 'RAM'; })) {
      list.push({ icon: '🚀', key: 'RAM', val: v.split('\n')[0].split(',')[0].substring(0, 30) });
    } else if (/(ổ đĩa|ổ cứng|storage|ssd|hdd)/i.test(k) && !list.some(function (x) { return x.key === 'Ổ cứng'; })) {
      list.push({ icon: '💾', key: 'Ổ cứng', val: v.split('\n')[0].split(',')[0].substring(0, 30) });
    } else if (/tốc độ in/i.test(k) && !list.some(function (x) { return x.key === 'Tốc độ'; })) {
      list.push({ icon: '🖨️', key: 'Tốc độ', val: v.split('\n')[0].split(';')[0].substring(0, 30) });
    } else if (/khổ giấy/i.test(k) && !list.some(function (x) { return x.key === 'Khổ in'; })) {
      list.push({ icon: '📄', key: 'Khổ in', val: v.split('\n')[0].split(';')[0].substring(0, 30) });
    } else if (/(khay giấy|trữ lượng)/i.test(k) && !list.some(function (x) { return x.key === 'Khay giấy'; })) {
      list.push({ icon: '📥', key: 'Khay giấy', val: v.split('\n')[0].split(';')[0].substring(0, 30) });
    } else if (/duplex|in 2 mặt/i.test(k) && !list.some(function (x) { return x.key === 'In 2 mặt'; })) {
      list.push({ icon: '🔄', key: 'In 2 mặt', val: v.split('\n')[0].substring(0, 25) });
    }
  });
  return list;
}

function openProductSpecModal(id, ev) {
  if (ev) {
    if (typeof ev.stopPropagation === 'function') ev.stopPropagation();
    if (typeof ev.preventDefault === 'function') ev.preventDefault();
  }
  var item = CATALOG_ITEMS.find(function (x) { return x.id === id; });
  if (!item) {
    if (CATALOG_ITEMS.length > 0) item = CATALOG_ITEMS[0];
    else return;
  }
  currentSpecModalItemId = item.id;

  // Highlight active row in catalog table
  document.querySelectorAll('.cat-table tr').forEach(function (r) { r.classList.remove('spec-active-row'); });
  var targetRow = ev && ev.target ? ev.target.closest('tr, .cat-card') : null;
  if (targetRow) targetRow.classList.add('spec-active-row');

  // Populate or sync device dropdown
  var sel = document.getElementById('specModalDeviceSelect');
  if (sel) {
    if (sel.options.length !== CATALOG_ITEMS.length) {
      sel.innerHTML = CATALOG_ITEMS.map(function (it) {
        return '<option value="' + it.id + '">' + escH(it.name) + ' (' + escH(it.model || 'N/A') + ')</option>';
      }).join('');
    }
    sel.value = item.id;
  }

  // Update header elements
  var badgeEl = document.getElementById('specModalBadge');
  if (badgeEl) {
    var catLabels = {
      'may_tinh': '💻 Máy tính',
      'man_hinh': '🖥️ Màn hình',
      'may_in': '🖨️ Máy in',
      'photocopy': '📠 Photocopy',
      'may_scan': '📄 Máy Scan'
    };
    badgeEl.textContent = catLabels[item.cat] || '🌐 Thiết bị khác';
  }

  var brandEl = document.getElementById('specModalBrand');
  if (brandEl) brandEl.textContent = item.brand || 'Chính hãng';

  var titleEl = document.getElementById('specModalTitle');
  if (titleEl) titleEl.textContent = item.name;

  var metaEl = document.getElementById('specModalMeta');
  if (metaEl) {
    metaEl.innerHTML = '<b>Model:</b> ' + escH(item.model || 'N/A') +
      ' | <b>Bảo hành:</b> ' + escH(item.warranty || '12 tháng') +
      (item.price ? ' | <b>Đơn giá:</b> <b style="color:var(--go)">' + fmtVN(item.price) + 'đ</b>' : '');
  }

  // Update toggle select button
  updateSpecModalSelectButton();

  // Load specs
  currentSpecModalList = getDeviceSpecs(item);

  // Clear filter input
  var filterInp = document.getElementById('specFilterInput');
  if (filterInp) filterInp.value = '';

  // Render spec compact grid & table
  renderModalSpecTable(currentSpecModalList, '');

  // Reset view mode to grid default
  setSpecDisplayMode(specDisplayMode || 'grid');

  // Display modal centered in the middle of screen
  var modal = document.getElementById('productSpecModal');
  var card = document.getElementById('specModalCard');
  if (modal) {
    modal.style.display = 'flex';
    document.body.style.overflow = 'hidden'; // prevent background scrolling

    if (card) {
      card.style.position = '';
      card.style.top = '';
      card.style.transform = '';
      var modalBody = (card && card.querySelector) ? card.querySelector('.spec-modal-body') : null;
      if (modalBody) modalBody.scrollTop = 0;
    }

    if (filterInp) setTimeout(function () { filterInp.focus(); }, 150);
  }
}

function updateSpecModalSelectButton() {
  var btn = document.getElementById('specModalToggleSelectBtn');
  if (!btn || !currentSpecModalItemId) return;
  var isSel = typeof selectedCatalogItems !== 'undefined' && !!selectedCatalogItems[currentSpecModalItemId];
  var q = (isSel && selectedCatalogItems[currentSpecModalItemId]) ? selectedCatalogItems[currentSpecModalItemId].qty : 1;
  btn.textContent = isSel ? '✕ Bỏ Chọn (' + q + ')' : '✓ Chọn Vào Dự Toán';
  btn.className = isSel ? 'btn btn-d btn-sm' : 'btn btn-p btn-sm';
}

function closeProductSpecModal() {
  var modal = document.getElementById('productSpecModal');
  if (modal) modal.style.display = 'none';
  var card = document.getElementById('specModalCard');
  if (card) {
    card.style.position = '';
    card.style.top = '';
  }
  document.body.style.overflow = ''; // restore scrolling
  document.querySelectorAll('.cat-table tr').forEach(function (r) { r.classList.remove('spec-active-row'); });
}

function filterModalSpecs(query) {
  renderModalSpecTable(currentSpecModalList, query);
}

function clearModalSpecFilter() {
  var filterInp = document.getElementById('specFilterInput');
  if (filterInp) {
    filterInp.value = '';
    filterInp.focus();
  }
  renderModalSpecTable(currentSpecModalList, '');
}

function highlightSpecText(text, query) {
  if (!text) return '';
  var escaped = escH(text);
  if (!query) return escaped.replace(/\r\n|\n/g, '<br/>');
  var parts = query.split('|').map(function (p) { return p.trim(); }).filter(Boolean);
  if (parts.length === 0) return escaped.replace(/\r\n|\n/g, '<br/>');

  var pattern = parts.map(function (p) {
    return escH(p).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }).join('|');

  try {
    var regex = new RegExp('(' + pattern + ')', 'gi');
    return escaped.replace(regex, '<mark class="spec-highlight">$1</mark>').replace(/\r\n|\n/g, '<br/>');
  } catch (e) {
    return escaped.replace(/\r\n|\n/g, '<br/>');
  }
}

function renderModalSpecTable(specs, query) {
  var tbody = document.getElementById('specModalTableBody');
  var gridWrap = document.getElementById('specCompactGrid');
  var highlightsBar = document.getElementById('specModalKeyHighlights');
  var counter = document.getElementById('specMatchCounter');

  var q = (query || '').toLowerCase().trim();
  var qParts = q ? q.split('|').map(function (p) { return p.trim(); }).filter(Boolean) : [];

  // Render Key Highlights Bar
  if (highlightsBar) {
    var keyHighlights = extractKeyHighlights(specs);
    if (keyHighlights.length > 0) {
      highlightsBar.style.display = 'flex';
      highlightsBar.innerHTML = '<span style="font-size:11px;font-weight:700;color:var(--t3);margin-right:2px">✨ Cấu hình nổi bật:</span>' +
        keyHighlights.map(function (hl) {
          return '<span class="spec-hl-pill ' + (hl.theme || '') + '">' + hl.icon + ' <b>' + escH(hl.key) + ':</b> ' + escH(hl.val) + '</span>';
        }).join('');
    } else {
      highlightsBar.style.display = 'none';
    }
  }

  var filtered = specs.filter(function (s) {
    if (!q || qParts.length === 0) return true;
    var k = (s.key || '').toLowerCase();
    var v = (s.value || '').toLowerCase();
    return qParts.some(function (p) {
      return k.includes(p) || v.includes(p);
    });
  });

  if (counter) {
    counter.textContent = filtered.length + ' / ' + specs.length + ' thông số' + (q ? ' (khớp)' : '');
    counter.style.background = q && filtered.length === 0 ? '#fee2e2' : 'var(--p-light)';
    counter.style.color = q && filtered.length === 0 ? '#b91c1c' : 'var(--p)';
  }

  if (filtered.length === 0) {
    var emptyHtml = '<div style="grid-column:1/-1;text-align:center;padding:24px;color:var(--t2)">' +
      '🔍 Không tìm thấy thông số nào khớp với từ khóa "<b>' + escH(query) + '</b>".' +
      '<br/><button class="btn btn-o btn-sm" onclick="clearModalSpecFilter()" style="margin-top:10px">✕ Xóa bộ lọc</button>' +
      '</div>';
    if (gridWrap) gridWrap.innerHTML = emptyHtml;
    if (tbody) tbody.innerHTML = '<tr><td colspan="3" style="text-align:center;padding:24px;color:var(--t2)">' + emptyHtml + '</td></tr>';
    return;
  }

  // 1. Render 2-Column Compact Grid (Gọn gàng không phải cuộn)
  if (gridWrap) {
    gridWrap.innerHTML = filtered.map(function (s, idx) {
      var keyH = highlightSpecText(s.key, q);
      var valH = highlightSpecText(s.value, q);
      return '<div class="spec-grid-card">' +
        '<div class="spec-gc-hdr">' +
        '<span class="spec-gc-idx">' + (idx + 1) + '</span>' +
        '<span class="spec-gc-key">' + keyH + '</span>' +
        '</div>' +
        '<div class="spec-gc-val">' + valH + '</div>' +
        '</div>';
    }).join('');
  }

  // 2. Render Traditional Table (Khi chuyển sang tab Bảng)
  if (tbody) {
    tbody.innerHTML = filtered.map(function (s, idx) {
      var keyH = highlightSpecText(s.key, q);
      var valH = highlightSpecText(s.value, q);
      return '<tr>' +
        '<td style="text-align:center;font-weight:700;color:var(--t3)">' + (idx + 1) + '</td>' +
        '<td style="font-weight:600;color:var(--t1)">' + keyH + '</td>' +
        '<td style="color:var(--t2);line-height:1.55">' + valH + '</td>' +
        '</tr>';
    }).join('');
  }
}

function toggleSpecModalSelect() {
  if (!currentSpecModalItemId) return;
  toggleCatalogItem(currentSpecModalItemId);
  updateSpecModalSelectButton();
}

function copyProductSpecsToClipboard() {
  if (!currentSpecModalItemId || !currentSpecModalList || currentSpecModalList.length === 0) {
    if (typeof toast === 'function') toast('Không có thông số để sao chép', '⚠️');
    return;
  }
  var item = CATALOG_ITEMS.find(function (x) { return x.id === currentSpecModalItemId; });
  var title = item ? item.name : 'Thiết bị';
  var model = item ? item.model : '';
  var brand = item ? item.brand : '';

  var textLines = [];
  textLines.push('THÔNG SỐ KỸ THUẬT: ' + title);
  if (model || brand) textLines.push('Model: ' + model + ' | Hãng: ' + brand);
  textLines.push('--------------------------------------------------');

  currentSpecModalList.forEach(function (s, idx) {
    textLines.push((idx + 1) + '. ' + s.key + ': ' + (s.value || '').replace(/\r\n|\n/g, '; '));
  });

  var fullText = textLines.join('\n');
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(fullText).then(function () {
      if (typeof toast === 'function') toast('Đã copy toàn bộ ' + currentSpecModalList.length + ' thông số kỹ thuật vào clipboard!', '✅');
    }).catch(function () {
      fallbackCopyText(fullText);
    });
  } else {
    fallbackCopyText(fullText);
  }
}

function fallbackCopyText(text) {
  var ta = document.createElement('textarea');
  ta.value = text;
  ta.style.position = 'fixed';
  ta.style.left = '-9999px';
  document.body.appendChild(ta);
  ta.select();
  try {
    document.execCommand('copy');
    if (typeof toast === 'function') toast('Đã copy thông số kỹ thuật!', '✅');
  } catch (e) {
    if (typeof toast === 'function') toast('Không thể copy tự động, vui lòng chọn thủ công', '❌');
  }
  document.body.removeChild(ta);
}

function menuOpenSpecInspector() {
  var id = currentSpecModalItemId || (CATALOG_ITEMS.length > 0 ? CATALOG_ITEMS[0].id : null);
  if (id) {
    openProductSpecModal(id);
  } else {
    if (typeof toast === 'function') toast('Chưa có danh sách thiết bị để tra cứu', '⚠️');
  }
}

// Global keydown handler for Escape key closing modals
window.addEventListener('keydown', function (e) {
  if (e.key === 'Escape') {
    closeProductSpecModal();
    if (typeof closeAllMenus === 'function') closeAllMenus();
  }
});


// ══════════════════════════════════════════════════════════════════════════════
// PARAMETRIC SPECIFICATION FILTER CONTROLLERS (GB, Tốc độ, Khay giấy, Khổ A3...)
// ══════════════════════════════════════════════════════════════════════════════

function applyParametricFilter() {
  var ramEl = document.getElementById('specFilterRam');
  var speedEl = document.getElementById('specFilterSpeed');
  var paperEl = document.getElementById('specFilterPaper');
  var featEl = document.getElementById('specFilterFeature');

  specFilters.ram = ramEl ? ramEl.value : '';
  specFilters.speed = speedEl ? speedEl.value : '';
  specFilters.paper = paperEl ? paperEl.value : '';
  specFilters.feature = featEl ? featEl.value : '';

  updateSpecChipsUi();
  renderCatalogGrid();
  updateSpecFilterBanner();
}

function toggleSpecChip(btn, type, val) {
  var currentVal = specFilters[type];
  if (currentVal === val) {
    specFilters[type] = '';
  } else {
    specFilters[type] = val;
  }

  var selId = type === 'ram' ? 'specFilterRam' :
    type === 'speed' ? 'specFilterSpeed' :
    type === 'paper' ? 'specFilterPaper' : 'specFilterFeature';
  var selEl = document.getElementById(selId);
  if (selEl) selEl.value = specFilters[type];

  updateSpecChipsUi();
  renderCatalogGrid();
  updateSpecFilterBanner();
}

function updateSpecChipsUi() {
  var chips = document.querySelectorAll('.spec-chip');
  chips.forEach(function (chip) {
    var t = chip.getAttribute('data-type');
    var v = chip.getAttribute('data-val');
    if (specFilters[t] === v) {
      chip.classList.add('active');
    } else {
      chip.classList.remove('active');
    }
  });

  var clearBtn = document.getElementById('btnClearSpecFilters');
  var countEl = document.getElementById('activeSpecFilterCount');
  var activeCount = (specFilters.ram ? 1 : 0) + (specFilters.speed ? 1 : 0) + (specFilters.paper ? 1 : 0) + (specFilters.feature ? 1 : 0);
  if (countEl) countEl.textContent = activeCount;
  if (clearBtn) clearBtn.style.display = activeCount > 0 ? 'inline-flex' : 'none';
}

function updateSpecFilterBanner() {
  var banner = document.getElementById('specFilterActiveBanner');
  var textEl = document.getElementById('specFilterActiveText');
  var badgeEl = document.getElementById('specFilterResultBadge');
  if (!banner || !textEl) return;

  var activeLabels = [];
  var ramNames = {
    'ram_8gb': 'RAM 8GB',
    'ram_12_16gb': 'RAM 12-16GB',
    'storage_256gb': 'Ổ cứng/ROM 256GB',
    'storage_512gb': 'Ổ cứng SSD 512GB',
    'storage_1tb': 'Ổ cứng ≥ 1TB'
  };
  var speedNames = {
    'speed_lt25': 'Tốc độ < 25 tr/phút',
    'speed_25_35': 'Tốc độ 25-35 tr/phút',
    'speed_gt35': 'Tốc độ > 35 tr/phút'
  };
  var paperNames = {
    'paper_lt150': 'Khay < 150 tờ',
    'paper_gte250': 'Khay ≥ 250 tờ',
    'paper_gte500': 'Khay ≥ 500 tờ'
  };
  var featNames = {
    'paper_a3': 'Khổ in/quét A3',
    'duplex': 'In 2 mặt Duplex',
    'wifi': 'Kết nối Wi-Fi',
    'lan': 'Cổng mạng LAN'
  };

  if (specFilters.ram) activeLabels.push(ramNames[specFilters.ram] || specFilters.ram);
  if (specFilters.speed) activeLabels.push(speedNames[specFilters.speed] || specFilters.speed);
  if (specFilters.paper) activeLabels.push(paperNames[specFilters.paper] || specFilters.paper);
  if (specFilters.feature) activeLabels.push(featNames[specFilters.feature] || specFilters.feature);

  if (activeLabels.length === 0) {
    banner.style.display = 'none';
  } else {
    banner.style.display = 'flex';
    textEl.textContent = activeLabels.join(' + ');
    var filtered = getFilteredCatalogItems();
    if (badgeEl) badgeEl.textContent = 'Tìm thấy ' + filtered.length + ' máy';
  }
}

function resetParametricFilters() {
  specFilters.ram = '';
  specFilters.speed = '';
  specFilters.paper = '';
  specFilters.feature = '';

  ['specFilterRam', 'specFilterSpeed', 'specFilterPaper', 'specFilterFeature'].forEach(function (id) {
    var el = document.getElementById(id);
    if (el) el.value = '';
  });

  updateSpecChipsUi();
  renderCatalogGrid();
  updateSpecFilterBanner();
}

function toggleSpecFilterPanel() {
  var body = document.getElementById('csfpBody');
  var btnTxt = document.getElementById('txtToggleSpecPanel');
  var btn = document.getElementById('btnToggleSpecPanel');
  if (!body) return;
  if (body.style.display === 'none') {
    body.style.display = 'block';
    if (btnTxt) btnTxt.textContent = 'Thu gọn';
    if (btn) btn.innerHTML = '<span id="txtToggleSpecPanel">Thu gọn</span> ▴';
  } else {
    body.style.display = 'none';
    if (btnTxt) btnTxt.textContent = 'Mở bộ lọc';
    if (btn) btn.innerHTML = '<span id="txtToggleSpecPanel">Mở bộ lọc</span> ▾';
  }
}

function quickFilterModalSpec(pattern) {
  var filterInp = document.getElementById('specFilterInput');
  if (filterInp) {
    filterInp.value = pattern;
  }
  filterModalSpecs(pattern);
}

function toggleSidebar() {
  var sb = document.getElementById('appSidebar');
  if (!sb) return;
  sb.classList.toggle('collapsed');
  var isCol = sb.classList.contains('collapsed');
  try { localStorage.setItem('sidebar_collapsed', isCol ? '1' : '0'); } catch(e){}
}

try {
  if (typeof localStorage !== 'undefined' && localStorage.getItem('sidebar_collapsed') === '1') {
    var sb = document.getElementById('appSidebar');
    if (sb) sb.classList.add('collapsed');
  }
} catch(e){}
